namespace A33.Instrument.Protocol;
public enum WordOrder { HighWordFirst, LowWordFirst }
public static class RegisterValueCodec { public static long Int64(ReadOnlySpan<ushort> words,WordOrder order=WordOrder.HighWordFirst){if(words.Length<4)throw new ArgumentException("four registers required");ulong v=0;for(var i=0;i<4;i++){var w=order==WordOrder.HighWordFirst?words[i]:words[3-i];v=(v<<16)|w;}return unchecked((long)v);} public static int Int32(ReadOnlySpan<ushort> words,WordOrder order=WordOrder.HighWordFirst){if(words.Length<2)throw new ArgumentException("two registers required");var v=order==WordOrder.HighWordFirst?(uint)words[0]<<16|words[1]:(uint)words[1]<<16|words[0];return unchecked((int)v);} public static ushort[] FromInt64(long value,WordOrder order=WordOrder.HighWordFirst){var u=unchecked((ulong)value);var a=new ushort[]{(ushort)(u>>48),(ushort)(u>>32),(ushort)(u>>16),(ushort)u};return order==WordOrder.HighWordFirst?a:a.Reverse().ToArray();} }
